example.code:
import { useForm } from '@conform-to/react';

export default function TasksForm() {
  const [form, fields] = useForm({
    defaultValue: { tasks: ['Write docs'] },
  });
  const tasks = fields.tasks.getFieldList();

  return (
    <form {...form.props}>
      <ul>
        {tasks.map((task, index) => (
          <li key={task.key}>
            <input name={task.name} defaultValue={task.value} />
            <button {...form.remove(fields.tasks.name, { index })}>Remove</button>
          </li>
        ))}
      </ul>
      <button {...form.insert(fields.tasks.name, { defaultValue: '' })}>Add</button>
      <button {...form.reorder(fields.tasks.name, { from: 0, to: 1 })}>Move first</button>
    </form>
  );
}

